function haversineKm(a,b,c,d){const r=6371,p=Math.PI/180,da=(c-a)*p,db=(d-b)*p,q=Math.sin(da/2)**2+Math.cos(a*p)*Math.cos(c*p)*Math.sin(db/2)**2;return 2*r*Math.asin(Math.sqrt(q))}
function applyCampusMetrics(){const campus=milanCampuses[state.campus];if(!campus)return;state.items.filter(x=>x.city==='Milano'&&Number.isFinite(x.lat)&&Number.isFinite(x.lng)).forEach(x=>{const km=haversineKm(x.lat,x.lng,campus.lat,campus.lng)*1.18;x.campusReference={campusId:state.campus,campusName:campus.name,distanceKm:Number(km.toFixed(1)),minutesBike:Math.max(2,Math.round(km/15*60)),travelEstimate:true}})}
