function distanceWithRoute(x){const url=routeUrl(x);return `${distanceText(x)}${url?`<br><a class="routelink" href="${url}" target="_blank" rel="noopener noreferrer">🚲 Apri percorso</a>`:''}`}
function statisticalSignals(x){const out=[],peers=state.items.filter(i=>i.city===x.city),knownCosts=peers.filter(i=>i.realMonthlyCostStatus==='complete'&&Number.isFinite(i.realMonthlyCost)).map(i=>i.realMonthlyCost),knownDistances=peers.map(i=>i.campusReference?.distanceKm).filter(Number.isFinite),knownDates=peers.map(i=>i.availability?.availableFrom).filter(Boolean).sort();if(x.realMonthlyCostStatus==='complete'&&knownCosts.length){const avg=knownCosts.reduce((a,b)=>a+b,0)/knownCosts.length,min=Math.min(...knownCosts);out.push(x.realMonthlyCost===min?'🏆 Costo reale più basso':x.realMonthlyCost<=avg?'📉 Costo sotto la media delle schede':'📈 Costo sopra la media delle schede')}else out.push('⚠️ Costo reale da completare');if(Number.isFinite(x.campusReference?.distanceKm)&&knownDistances.length){const avg=knownDistances.reduce((a,b)=>a+b,0)/knownDistances.length,min=Math.min(...knownDistances);out.push(x.campusReference.distanceKm===min?'🎯 Più vicino alla sede':x.campusReference.distanceKm<=avg?'📍 Distanza sotto la media':'📍 Distanza sopra la media')}if(x.availability?.availableFrom&&knownDates.length&&x.availability.availableFrom===knownDates[0])out.push('⭐ Disponibile prima delle altre');const complete=[x.validation?.expensesDeclared,x.validation?.contractDeclared,x.validation?.utilitiesDeclared,Boolean(x.availability?.availableFrom)].filter(Boolean).length;if(out.length<2)out.push(complete===4?'✓ Dati chiave completi':`◔ ${complete}/4 dati chiave completi`);return out.slice(0,3)}
function signalClass(s){return /sopra la media|da completare|[0-3]\/4/.test(s)?' warn':''}
const demoSurroundings={centro:[['🛒 Supermercato','6 min a piedi'],['🚌 Fermata bus','3 min a piedi'],['🏋️ Palestra','8 min in bici'],['☕ Servizi essenziali','entro 5 min']],mammut:[['🛒 Supermercato','7 min a piedi'],['🚌 Fermata bus','4 min a piedi'],['🏋️ Palestra','6 min in bici'],['💊 Farmacia','entro 6 min']],darsena:[['🛒 Supermercato','5 min a piedi'],['🚌 Fermata bus','5 min a piedi'],['🏋️ Palestra','7 min in bici'],['☕ Servizi essenziali','entro 7 min']]};
function detailMapBlock(x){if(!Number.isFinite(x.lat)||!Number.isFinite(x.lng))return'';const d=.006,bbox=[x.lng-d,x.lat-d,x.lng+d,x.lat+d].join('%2C'),src=`https://www.openstreetmap.org/export/embed.html?bbox=${bbox}&layer=mapnik&marker=${x.lat}%2C${x.lng}`,nearby=demoSurroundings[x.campusReference?.campusId]||[];return `<section class="detailmapcard"><div class="detailmaphead"><h3>📍 Dove si trova</h3><a class="routelink" href="${routeUrl(x)}" target="_blank" rel="noopener noreferrer">🚲 Apri percorso</a></div><iframe title="Mappa dell’alloggio" loading="lazy" src="${src}"></iframe><div class="surroundings"><h3>Nei dintorni</h3><div class="surroundingsgrid">${nearby.map(([name,time])=>`<div class="surroundingitem"><b>${name}</b>${time}</div>`).join('')}</div><p class="demohint">Tempi e servizi saranno calcolati e verificati per ogni indirizzo.</p></div></section>`}
function highlightCard(id){document.querySelectorAll('.card.map-highlight').forEach(el=>el.classList.remove('map-highlight'));const card=document.getElementById(`listing-card-${Number(id)}`);if(!card)return;card.classList.add('map-highlight');setTimeout(()=>card.classList.remove('map-highlight'),6000)}
function highlightMapMini(id){document.querySelectorAll('.mapmini.active').forEach(el=>el.classList.remove('active'));const mini=document.getElementById(`map-mini-${Number(id)}`);if(!mini)return;mini.classList.add('active');mini.scrollIntoView({behavior:'smooth',block:'nearest',inline:'nearest'})}
function mapMini(x){const id=Number(x.id);return `<button class="mapmini" id="map-mini-${id}" onclick="openDetail(${id})"><span class="mapminiphoto photo ${photoClass(x)}" ${photoStyle(x)} data-label="${photoLabel(x)}"></span><span class="mapminibody"><small>${x.city} · ${campusShort(x)}</small><strong>${x.title}</strong><b>${euro(x.price)} <em>/ mese</em></b><span>${distanceText(x)}</span></span></button>`}
