function initMap(id='demo-map',items=state.items,attempt=0){const el=document.getElementById(id);if(!el)return;if(!window.L){if(attempt<30)setTimeout(()=>initMap(id,items,attempt+1),150);return}const map=L.map(el,{scrollWheelZoom:false,tap:true,zoomControl:true}).setView([44.835,11.619],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors',crossOrigin:true}).addTo(map);const bounds=[];items.filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lng)).forEach(x=>{const selected=state.selected.has(Number(x.id)),favorite=state.favs.has(Number(x.id)),marker=L.circleMarker([x.lat,x.lng],{radius:selected?15:favorite?12:10,weight:selected?5:favorite?4:3,color:selected?'#d89b00':favorite?'#c43f65':'#fff',fillColor:selected?'transparent':favorite?'#f6bfd0':'#a84d3f',fillOpacity:selected?0:1});marker.addTo(map).bindTooltip(`${favorite?'♥ ':''}${selected?'★ ':''}${euro(x.price)}`,{permanent:true,direction:'top',offset:[0,selected?-12:-8],className:`listing-price-tooltip${selected?' selected-map-label':''}`}).bindPopup(`<b>${favorite?'♥ Preferito · ':''}${selected?'★ Selezionato · ':''}${x.title}</b><br>${euro(x.price)} / mese<br><small>${x.locationStatus==='approximate_area'?'Posizione indicativa':'Posizione verificata sulla via'}</small><br><button class="pinopen" onclick="openDetail(${Number(x.id)})">Apri la scheda</button>`);marker.on('click',()=>{highlightMapMini(x.id);if(id==='home-map')highlightCard(x.id)});if(selected||favorite)marker.bringToFront();bounds.push([x.lat,x.lng])});if(bounds.length===1)map.setView(bounds[0],15);else if(bounds.length>1)map.fitBounds(bounds,{padding:[55,55],maxZoom:14});requestAnimationFrame(()=>map.invalidateSize());setTimeout(()=>map.invalidateSize(),300)}
function nav(){return `<nav class="v3nav"><button class="${state.view==='list'?'active':''}" onclick="setView('list')">⌂ Alloggi <b>${sorted().length}</b></button><button class="${state.view==='map'?'active':''}" onclick="setView('map')">⌖ Mappa</button><button class="${state.view==='favs'?'active':''}" onclick="setView('favs')">♡ Preferiti <b>${state.favs.size}</b></button><button class="${state.view==='alerts'?'active':''}" onclick="setView('alerts')">♧ Alert</button></nav>`}
function filters(){const chips=[['wifi','Wi-Fi'],['lavatrice','Lavatrice'],['bagno','Bagno'],['cucina','Cucina']],landingCampus=state.campus&&milanCampuses[state.campus],landingName=landingCampus?.name.split('·')[0].trim(),active=state.city||state.campus||state.neededFrom||state.maxPrice||state.zone||state.source||state.maxDistance||state.quick.size,place=state.city==='Milano'?`<label class="note">Sede di studio<select onchange="setCampus(this.value)"><option value="" ${!state.campus?'selected':''}>Scegli sede</option>${Object.entries(milanCampuses).map(([id,c])=>`<option value="${id}" ${state.campus===id?'selected':''}>${c.name}</option>`).join('')}</select></label>`:`<label class="note">Zona / polo<select onchange="setZone(this.value)"><option value="" ${!state.zone?'selected':''}>Tutte le zone</option><option value="centro" ${state.zone==='centro'?'selected':''}>Centro</option><option value="mammut" ${state.zone==='mammut'?'selected':''}>Mammut</option><option value="darsena" ${state.zone==='darsena'?'selected':''}>Darsena</option></select></label>`;return `<section class="panel filterpanel"><div class="filtertitle"><div><h2 class="section-title">${landingName?`Alloggi per studenti vicino a ${landingName}`:'Trova il tuo posto'}</h2>${landingName?`<p class="campuslandingintro">Confronta costi, disponibilità e distanza dalla sede.</p>`:''}</div>${active?`<button class="resetfilters" onclick="clearFilters()">Azzera</button>`:''}</div><div class="universalfilters"><label class="note">Città<select onchange="setCity(this.value)"><option value="" ${!state.city?'selected':''}>Scegli città</option><option value="Ferrara" ${state.city==='Ferrara'?'selected':''}>Ferrara</option><option value="Milano" ${state.city==='Milano'?'selected':''}>Milano</option></select></label><label class="note">Fonte degli annunci<select onchange="setSource(this.value)"><option value="" ${!state.source?'selected':''}>Tutte le fonti attive</option><option value="direct" ${state.source==='direct'?'selected':''}>Offerenti diretti</option><option value="institutional" ${state.source==='institutional'?'selected':''}>Enti e residenze</option><option value="portal" ${state.source==='portal'?'selected':''}>Portali collegati</option></select></label></div><div class="primaryfilters"><label class="note">Mi serve dal<input type="date" value="${state.neededFrom}" onchange="setNeededFrom(this.value)"></label>${place}<label class="note">Budget massimo<select onchange="setMaxPrice(this.value)"><option value="" ${!state.maxPrice?'selected':''}>Qualsiasi</option><option value="400" ${state.maxPrice==='400'?'selected':''}>Fino a €400</option><option value="500" ${state.maxPrice==='500'?'selected':''}>Fino a €500</option><option value="600" ${state.maxPrice==='600'?'selected':''}>Fino a €600</option><option value="800" ${state.maxPrice==='800'?'selected':''}>Fino a €800</option><option value="1200" ${state.maxPrice==='1200'?'selected':''}>Fino a €1.200</option><option value="1800" ${state.maxPrice==='1800'?'selected':''}>Fino a €1.800</option></select></label></div><div class="quickchips"><button class="filterchip more ${state.moreFilters?'on':''}" onclick="toggleMore()">${state.moreFilters?'− Meno filtri':'+ Altri filtri'}</button></div>${state.moreFilters?`<div class="morefilterbox"><div class="quickchips">${chips.map(([v,l])=>`<button class="filterchip ${state.quick.has(v)?'on':''}" onclick="toggleQuick('${v}')">${l}</button>`).join('')}</div><label class="note">Distanza dalla sede<select onchange="setMaxDistance(this.value)"><option value="" ${!state.maxDistance?'selected':''}>Qualsiasi</option><option value="1" ${state.maxDistance==='1'?'selected':''}>Entro 1 km</option><option value="2" ${state.maxDistance==='2'?'selected':''}>Entro 2 km</option><option value="3" ${state.maxDistance==='3'?'selected':''}>Entro 3 km</option><option value="5" ${state.maxDistance==='5'?'selected':''}>Entro 5 km</option><option value="8" ${state.maxDistance==='8'?'selected':''}>Entro 8 km</option></select></label><label class="note">Mostrami prima<select onchange="setSort(this.value)"><option value="date" ${state.sort==="date"?"selected":""}>Adatti alla mia data</option><option value="price" ${state.sort==="price"?"selected":""}>Meno costosi</option><option value="distance" ${state.sort==="distance"?"selected":""}>Più vicini alla sede</option><option value="availability" ${state.sort==="availability"?"selected":""}>Disponibili prima</option></select></label></div>`:''}<div class="resultline"><b>${sorted().length}</b> ${sorted().length===1?'alloggio':'alloggi'} a ${state.city}${active?' con questi filtri':''}</div></section>`}
const baseFilters=filters;
filters=function(){
  let html=baseFilters();
  html=html.replace('<select onchange="setCity(this.value)">',`<select onchange="setCity(this.value)"><option value="" ${!state.city?'selected':''}>Tutte le città</option>`);
  if(state.city==='Milano')html=html.replace('<select onchange="setCampus(this.value)">',`<select onchange="setCampus(this.value)"><option value="" ${!state.campus?'selected':''}>Tutte le sedi</option>`);
  if(!state.city){
    html=html.replace(/<label class="note">Zona \/ polo<select[\s\S]*?<\/select><\/label>/,`<label class="note">Sede / zona<select disabled><option>Tutte le sedi e zone</option></select></label>`);
    html=html.replace(` a ${state.city}${state.neededFrom||state.maxPrice||state.zone||state.source||state.maxDistance||state.quick.size?' con questi filtri':''}`,`${state.neededFrom||state.maxPrice||state.zone||state.source||state.maxDistance||state.quick.size?' con questi filtri':''}`);
  }
  return html;
}
function compareDock(){const n=state.selected.size;if(n<2)return"";return `<div class="comparedock" role="dialog" aria-label="Alloggi pronti per il confronto"><span><b>${n}</b> alloggi selezionati</span><button onclick="openComparison()">${state.compareSeen?'↩ Riapri confronto':'Confronta ora'}</button></div>`}
function difference(vals){return new Set(vals.map(v=>String(v).trim().toLowerCase())).size>1}
function comparison(){const xs=state.items.filter(x=>state.selected.has(Number(x.id)));if(xs.length<2)return"";const rows=[['💶 Canone mensile',x=>euro(x.price),x=>x.price,'🏅 Miglior canone'],['🧾 Costo reale stimato',costText,x=>x.realMonthlyCostStatus==='complete'?x.realMonthlyCost:null,'🏆 Miglior costo reale'],['📍 Distanza stimata dalla sede',distanceWithRoute,x=>x.campusReference?.distanceKm,'🎯 Più vicino'],['🚲 Tempo in bici stimato',bikeTimeText,x=>x.campusReference?.minutesBike,'✓ Più rapido'],['📅 Disponibilità',availabilityText,x=>x.availability?.availableFrom?Date.parse(x.availability.availableFrom):null,'⭐ Disponibile prima'],['💡 Spese e utenze',utilitiesText,null,''],['📄 Contratto',contractText,null,''],['🏠 Dotazioni principali',x=>features(x).slice(0,4).join(', ')||'Da verificare',null,'']];if(state.neededFrom)rows.splice(5,0,['✅ Compatibilità con la tua data',x=>compatibility(x).label||'Da verificare',null,'']);return `<section class="compareview"><div class="comparehead"><button class="back" onclick="closeComparison()">← Torna agli alloggi</button><div class="comparehead-actions"><button class="comparemap" onclick="setView('map')">📍 Vedi sulla mappa</button><button class="clearcompare" onclick="clearComparison()">Azzera</button></div></div><h1>Confronta ciò che conta</h1><p class="note">Clicca una fotografia per riaprire la scheda. Distanze e tempi in bici sono stime orientative calcolate dalla posizione disponibile.</p><div class="comparecards count-${xs.length}">${xs.map(x=>`<div class="comparemini"><div class="comparethumb photo ${photoClass(x)}" ${photoStyle(x)} data-label="" role="button" tabindex="0" onclick="openDetail(${Number(x.id)})" onkeydown="if(event.key==='Enter')openDetail(${Number(x.id)})"></div><strong>${x.title}</strong><span>${euro(x.price)}${x.price!=null?' / mese':''}</span></div>`).join('')}</div><div class="comparetable">${rows.map(([label,fn,metric,badge])=>{const vals=xs.map(fn),diff=difference(vals),nums=metric?xs.map(metric):[],finite=nums.filter(Number.isFinite),best=finite.length>1&&new Set(finite).size>1?Math.min(...finite):null;return `<div class="comparerow ${diff?'isdiff':''}"><div class="comparelabel">${diff?'● ':''}${label}</div><div class="comparevalues" style="grid-template-columns:repeat(${xs.length},minmax(0,1fr))">${vals.map((v,i)=>`<div>${v}${best!==null&&nums[i]===best?`<span class="bestmark">${badge}</span>`:''}</div>`).join('')}</div></div>`}).join('')}</div><p class="note comparehint">● differenza tra gli alloggi · 🏅/🏆/🎯/⭐ valore migliore</p></section>`}
function actionBlock(x){const official=trackedSourceUrl(x,'action'),source=x.publication?.source||'fonte originale';if(official)return `<div class="actions"><a class="primaryaction" href="${official}" target="_blank" rel="noopener noreferrer">Vai a ${source} ↗</a></div><p class="note">FUORISEDE non gestisce candidature o assegnazioni per questa soluzione.</p>`;return `<div class="actions"><button class="secondaryaction" onclick="unavailableAction('Il recapito dell’offerente non è ancora pubblicato.')">Contatto non ancora disponibile</button><button class="secondaryaction" onclick="unavailableAction('La funzione di segnalazione non è ancora attiva.')">Segnala</button></div>`}
function card(x){const c=compatibility(x),id=Number(x.id),fs=features(x).slice(0,2),applied=state.applied.has(id),signals=statisticalSignals(x);return `<article class="card" id="listing-card-${id}"><div class="photo ${photoClass(x)}" ${photoStyle(x)} data-label="${photoLabel(x)}" onclick="openDetail(${id})"></div><div class="cardbody"><div class="eyebrow">${x.city} · ${campusShort(x)}</div><div class="favline"><div class="cardclick" onclick="openDetail(${id})"><div class="title">${x.title}</div><div class="price">${euro(x.price)} <span class="muted">/ mese</span></div></div><button class="heart" aria-label="Preferito" onclick="toggleFav(${id})">${state.favs.has(id)?"♥":"♡"}</button></div><div><span class="badge">📅 ${availabilityText(x)}</span>${c.label?`<span class="badge ${c.rank===0?"":"warn"}">${c.label}</span>`:""}</div>${fs.length?`<div class="features">${fs.map(f=>`<span class="badge">${f}</span>`).join("")}</div>`:""}<div class="features"><span class="badge warn">${x.realMonthlyCostStatus==='complete'?`Costo reale ${euro(x.realMonthlyCost)}`:'Costo reale da completare'}</span></div>${signals.length?`<div>${signals.map(s=>`<span class="statmark${signalClass(s)}">${s}</span>`).join('')}</div>`:''}${needsIntegration(x)?`<button class="integrationprompt" onclick="requestIntegration(${id})">✎ Dato incompleto · chiedi integrazione</button>`:''}<div class="cardactions"><button class="detailsbtn" onclick="openDetail(${id})">Scopri</button><button class="cardmaplink" onclick="showListingOnMap(${id})">⌖ Vedi sulla mappa</button><label class="comparebox"><input type="checkbox" style="width:auto" ${state.selected.has(id)?"checked":""} onchange="toggleCompare('${id}',this.checked)"> Confronta</label></div></div></article>`}
function detailView(x){const id=Number(x.id),checked=state.selected.has(id),sandbox=x.publication?.status==='sandbox',locationNote=x.locationStatus==='approximate_area'?'Posizione indicativa della zona; indirizzo da verificare.':'Apri la posizione sulla mappa.';return `${nav()}<section class="detail"><button class="back" onclick="closeDetail()">← Tutti gli alloggi</button><div class="detailphoto photo ${photoClass(x)}" ${photoStyle(x)} data-label="${photoLabel(x)}"></div><div class="detailbody">${gallery(x)}<div class="eyebrow">${sandbox?'DATI SANDBOX · NON PUBBLICATI':'SCHEDA AUTORIZZATA'} · ${x.city} · ${campusShort(x)}</div><div class="favline"><div><h1 class="detailtitle">${x.title}</h1><div class="price">${euro(x.price)} <span class="muted">/ mese</span></div></div><button class="heart" aria-label="Preferito" onclick="toggleFav(${id})">${state.favs.has(id)?"♥":"♡"}</button></div><div><span class="badge">📅 ${availabilityText(x)}</span>${sandbox?'<span class="badge warn">Ambiente di prova Immobiliare.it</span>':''}</div><h2 class="section-title detailsection">In breve</h2><p>${x.details?.description||''}</p><div>${features(x).map(f=>`<span class="badge">${f}</span>`).join("")}</div><h2 class="section-title detailsection">Costi e disponibilità</h2><div class="row"><span>Canone / mese</span><strong>${euro(x.price)}</strong></div><div class="row"><span>Costo reale stimato</span><strong>${costText(x)}</strong></div><div class="row"><span>Disponibilità</span><strong>${availabilityText(x)}</strong></div><div class="row"><span>Spese / utenze</span><strong>${utilitiesText(x)}</strong></div><div class="row"><span>Contratto</span><strong>${contractText(x)}</strong></div><div class="row"><span>Deposito</span><strong>${x.details?.deposit||"Da verificare"}</strong></div><div class="row"><span>Piano / ascensore</span><strong>${x.details?.floor||"Da verificare"}</strong></div><h2 class="section-title detailsection">Affidabilità delle informazioni</h2><div class="trustbox"><div class="trustitem"><span>📅 Disponibilità</span><strong>${statusText(x)}</strong></div><div class="trustitem"><span>💶 Spese</span><strong>${x.validation?.expensesDeclared?"Complete":"Da verificare"}</strong></div><div class="trustitem"><span>📄 Contratto</span><strong>${x.validation?.contractDeclared?"Dato presente":"Da verificare"}</strong></div><div class="trustitem"><span>✓ Ultima conferma</span><strong>${confirmationText(x)}</strong></div><p class="note trustnote">FUORISEDE distingue ciò che è confermato da ciò che deve essere verificato.</p></div><h2 class="section-title detailsection">Dove si trova</h2><div class="mapbox">📍 ${x.address}<br><b>${distanceText(x)} da ${campusShort(x)}</b><br><a class="maplink" href="${mapUrl(x)}" target="_blank" rel="noopener noreferrer">Apri su Google Maps ↗</a><p class="note">${locationNote}</p></div>${actionBlock(x)}<button class="compareaction ${checked?"active":""}" onclick="toggleCompare('${id}',${!checked})">${checked?"✓ Nel confronto":"⇄ Confronta"}</button></div></section>${compareDock()}`}
function render(){const root=document.getElementById("v3-root");if(state.compareOpen){root.innerHTML=nav()+comparison();return}if(state.detail){const x=state.items.find(i=>Number(i.id)===state.detail);root.innerHTML=x?detailView(x):"";return}if(state.view==='alerts'){root.innerHTML=nav()+`<section class="empty"><div class="emptyheart">♧</div><h2>Alert in preparazione</h2><p>La funzione di avviso non è ancora attiva nella versione operativa.</p><button class="detailsbtn" onclick="setView('list')">Torna agli alloggi</button></section>`;return}if(state.view==='map'){const xs=sorted();root.innerHTML=nav()+filters()+`<section class="mapview">${mapWorkspace(xs,'demo-map')}<p class="note">Seleziona un pin per evidenziare l’alloggio; seleziona la mini-scheda per aprirlo.</p></section>`+compareDock();setTimeout(()=>initMap('demo-map',xs),0);return}if(state.view==='favs'){const favs=sorted().filter(x=>state.favs.has(Number(x.id)));root.innerHTML=nav()+filters()+(favs.length?favs.map(card).join(""):`<section class="empty"><div class="emptyheart">♡</div><h2>Nessun preferito ancora</h2><p>Salva con il cuore gli alloggi che vuoi ritrovare e confrontare.</p><button class="detailsbtn" onclick="setView('list')">Guarda gli alloggi</button></section>`)+compareDock();return}const xs=sorted();const homeMap=xs.length?`<section class="mapview"><h2 class="section-title">Guarda dove sono</h2>${mapWorkspace(xs,'home-map')}<p class="note">Seleziona un pin per evidenziare l’alloggio; seleziona la mini-scheda per aprirlo.</p></section>`:'';root.innerHTML=nav()+filters()+(xs.length?xs.map(card).join(''):`<section class="empty"><h2>Nessun alloggio con questi filtri</h2><p>Prova ad allargare un po’ la ricerca.</p><button class="detailsbtn" onclick="clearFilters()">Azzera filtri</button></section>`)+homeMap+compareDock();if(xs.length)setTimeout(()=>initMap('home-map',xs),0)}
const originalDetailView=detailView;
detailView=function(x){const id=Number(x.id),applied=state.applied.has(id),signals=statisticalSignals(x);let html=originalDetailView(x);const addAction=(label,value,key)=>{html=html.replace(`<div class="row"><span>${label}</span><strong>${value}</strong></div>`,`<div class="row"><span>${label}</span><strong>${value}<br>${integrationLink(id,key)}</strong></div>`)};if(signals.length)html=html.replace('<h2 class="section-title detailsection">In breve</h2>',`<div>${signals.map(s=>`<span class="statmark${signalClass(s)}">${s}</span>`).join('')}</div><h2 class="section-title detailsection">In breve</h2>`);if(x.realMonthlyCostStatus!=='complete')addAction('Costo reale stimato',costText(x),'costo reale');if(!x.availability?.availableFrom||x.availability?.status==='to_reconfirm')addAction('Disponibilità',availabilityText(x),'disponibilità');if(!x.validation?.expensesDeclared)addAction('Spese / utenze',utilitiesText(x),'spese e utenze');if(!x.validation?.contractDeclared)addAction('Contratto',contractText(x),'contratto');if(!x.details?.deposit||/verificare/i.test(x.details.deposit))addAction('Deposito',x.details?.deposit||'Da verificare','deposito');if(!x.details?.floor||/verificare/i.test(x.details.floor))addAction('Piano / ascensore',x.details?.floor||'Da verificare','piano e ascensore');if(needsIntegration(x))html=html.replace('<h2 class="section-title detailsection">Affidabilità delle informazioni</h2>',`<button class="integrationprompt" onclick="requestIntegration(${id})">✎ Alcuni dati sono parziali o mancanti · chiedi integrazione</button><h2 class="section-title detailsection">Affidabilità delle informazioni</h2>`);html=html.replace('<div class="actions">',`${detailMapBlock(x)}<div class="actions">`);return html}
async function init(){try{applyInboundDiscovery();const r=await fetch("/data/listings-operativa-v3.json",{cache:"no-store"});if(!r.ok)throw new Error(r.status);state.items=(await r.json()).filter(x=>x.publication?.status!=="blocked");render();try{const sandbox=await fetch('/api/immobiliare?city=Milano',{cache:'no-store'});if(sandbox.ok){const data=await sandbox.json();const used=new Set(state.items.map(x=>Number(x.id)));let nextId=1000000;const imported=(data.items||[]).map(x=>{while(used.has(nextId))nextId++;const id=nextId++;used.add(id);return{...x,externalId:x.id,id}});state.items.push(...imported);applyCampusMetrics();}}catch(e){console.info('Sandbox Immobiliare.it non attiva')}document.querySelector('.preview').textContent=`UNIVERSALE · ${new Set(state.items.map(x=>x.city)).size} CITTÀ ATTIVE`;render()}catch(e){document.getElementById("v3-root").innerHTML='<section class="panel"><b>La vetrina non è disponibile in questo momento.</b></section>';console.error(e)}}init();
