const activeMapMarkers=new Map();
function mapMini(x,mapId){const id=Number(x.id);return `<button class="mapmini" id="map-mini-${id}" onclick="selectMapListing('${mapId}',${id})"><span class="mapminiphoto photo ${photoClass(x)}" ${photoStyle(x)} data-label="${photoLabel(x)}"></span><span class="mapminibody"><small>${x.city} · ${campusShort(x)}</small><strong>${x.title}</strong><b>${euro(x.price)} <em>/ mese</em></b><span>${distanceText(x)}</span></span></button>`}
function mapWorkspace(items,mapId){return `<div class="mapworkspace"><aside class="mapminilist" aria-label="Alloggi presenti sulla mappa">${items.map(x=>mapMini(x,mapId)).join('')}</aside><div class="mapcanvas"><div id="${mapId}" aria-label="Mappa interattiva degli alloggi in collaudo"></div></div></div>`}
function markerAppearance(x,active=false){const selected=state.selected.has(Number(x.id)),favorite=state.favs.has(Number(x.id));return{radius:active?17:selected?15:favorite?12:10,weight:active?6:selected?5:favorite?4:3,color:active?'#d89b00':selected?'#d89b00':favorite?'#c43f65':'#fff',fillColor:active?'#fff3b0':selected?'transparent':favorite?'#f6bfd0':'#a84d3f',fillOpacity:active?1:selected?0:1}}
function selectMapListing(mapId,id){highlightMapMini(id);const context=activeMapMarkers.get(mapId),entry=context?.markers.get(Number(id));if(!entry)return;context.markers.forEach(({marker,x})=>marker.setStyle(markerAppearance(x,false)));entry.marker.setStyle(markerAppearance(entry.x,true));entry.marker.bringToFront();entry.marker.openPopup();context.map.panTo(entry.marker.getLatLng())}
function initMap(id='demo-map',items=state.items,attempt=0){const el=document.getElementById(id);if(!el)return;if(!window.L){if(attempt<30)setTimeout(()=>initMap(id,items,attempt+1),150);return}const map=L.map(el,{scrollWheelZoom:false,tap:true,zoomControl:true}).setView([44.835,11.619],14);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap contributors',crossOrigin:true}).addTo(map);const bounds=[],markers=new Map();activeMapMarkers.set(id,{map,markers});items.filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lng)).forEach(x=>{const selected=state.selected.has(Number(x.id)),favorite=state.favs.has(Number(x.id)),marker=L.circleMarker([x.lat,x.lng],markerAppearance(x));marker.addTo(map).bindTooltip(`${favorite?'♥ ':''}${selected?'★ ':''}${euro(x.price)}`,{permanent:true,direction:'top',offset:[0,selected?-12:-8],className:`listing-price-tooltip${selected?' selected-map-label':''}`}).bindPopup(`<b>${favorite?'♥ Preferito · ':''}${selected?'★ Selezionato · ':''}${x.title}</b><br>${euro(x.price)} / mese<br><small>${x.locationStatus==='approximate_area'?'Posizione indicativa':'Posizione verificata sulla via'}</small><br><button class="pinopen" onclick="openDetail(${Number(x.id)})">Apri la scheda</button>`);markers.set(Number(x.id),{marker,x});marker.on('click',()=>{selectMapListing(id,x.id);if(id==='home-map')highlightCard(x.id)});if(selected||favorite)marker.bringToFront();bounds.push([x.lat,x.lng])});if(bounds.length===1)map.setView(bounds[0],15);else if(bounds.length>1)map.fitBounds(bounds,{padding:[55,55],maxZoom:14});requestAnimationFrame(()=>map.invalidateSize());setTimeout(()=>map.invalidateSize(),300)}

function listingIdFromCard(node){const card=node?.closest?.('.card');if(!card)return null;const id=Number(card.id.replace('listing-card-',''));return Number.isFinite(id)?id:null}
document.addEventListener('click',event=>{const id=listingIdFromCard(event.target);if(id===null)return;const heart=event.target.closest('.heart');if(heart){event.preventDefault();event.stopImmediatePropagation();toggleFav(id);return}if(event.target.closest('.comparebox')||event.target.closest('.cardmaplink'))return;event.preventDefault();event.stopImmediatePropagation();openDetail(id)},true);
document.addEventListener('change',event=>{if(!event.target.matches('.comparebox input'))return;const id=listingIdFromCard(event.target);if(id===null)return;event.stopImmediatePropagation();toggleCompare(id,event.target.checked)},true);
