const baseComparisonWithStats=comparison;
comparison=function(){let html=baseComparisonWithStats();const xs=state.items.filter(x=>state.selected.has(Number(x.id)));if(xs.length<2)return html;const values=xs.map(x=>statisticalSignals(x).find(s=>/media|più basso|più vicino|disponibile prima/i.test(s))||'Dati insufficienti per un confronto statistico');const note=`<div class="comparestatnote"><b>📊 Indicazione statistica secondaria</b><div class="comparestatvalues" style="grid-template-columns:repeat(${xs.length},minmax(0,1fr))">${values.map(v=>`<div>${v}</div>`).join('')}</div></div>`;return html.replace('</section>',`${note}</section>`)};

const orderedDetailView=detailView;
detailView=function(x){let html=orderedDetailView(x);const availability=/<div class="row"><span>Disponibilità<\/span>[\s\S]*?<\/div>/,expenses=/<div class="row"><span>Spese \/ utenze<\/span>[\s\S]*?<\/div>/;const a=html.match(availability)?.[0],e=html.match(expenses)?.[0];if(a&&e&&html.indexOf(a)<html.indexOf(e))html=html.replace(a,'__FUORISEDE_AVAILABILITY__').replace(e,`${e}${a}`).replace('__FUORISEDE_AVAILABILITY__','');return html};

function toggleCompareFromMap(id){const key=Number(id);toggleCompare(key,!state.selected.has(key))}
const localTileProxyTimer=setInterval(()=>{if(!window.L)return;clearInterval(localTileProxyTimer);if(!L.tileLayer.__fuorisedeProxy){const original=L.tileLayer;const proxied=function(url,options){const source=String(url).includes('tile.openstreetmap.org')?'/api/map-tile?z={z}&x={x}&y={y}':url;return original.call(this,source,options)};Object.assign(proxied,original);proxied.__fuorisedeProxy=true;L.tileLayer=proxied}if(!L.circleMarker.__fuorisedeCompare){const originalCircle=L.circleMarker;const enhanced=function(latlng,options){const marker=originalCircle.call(this,latlng,options),originalBind=marker.bindPopup;marker.bindPopup=function(content,...args){const match=String(content).match(/openDetail\((\d+)\)/);if(match&&!String(content).includes('pincompare'))content=String(content).replace('</button>',`</button><button class="pincompare" onclick="toggleCompareFromMap(${match[1]})">⇄ Confronta</button>`);return originalBind.call(this,content,...args)};return marker};Object.assign(enhanced,originalCircle);enhanced.__fuorisedeCompare=true;L.circleMarker=enhanced}if(state.items.length)render()},100);

const initMapWithCampus=initMap;
initMap=function(id='demo-map',items=state.items,attempt=0){initMapWithCampus(id,items,attempt);setTimeout(()=>{const campus=milanCampuses[state.campus],context=activeMapMarkers.get(id);if(!campus||!context||context.campusMarker)return;const icon=L.divIcon({className:'campuspin',html:'🎓',iconSize:[38,38],iconAnchor:[19,19]});context.campusMarker=L.marker([campus.lat,campus.lng],{icon,zIndexOffset:1000}).addTo(context.map).bindPopup(`<b>🎓 ${campus.name}</b><br><small>Sede di studio selezionata</small>`);context.campusMarker.bringToFront();const points=items.filter(x=>Number.isFinite(x.lat)&&Number.isFinite(x.lng)).map(x=>[x.lat,x.lng]);points.push([campus.lat,campus.lng]);if(points.length>1)context.map.fitBounds(points,{padding:[55,55],maxZoom:14})},40)};

const shareKey=x=>String(x.externalId??x.id);
function comparisonShareUrl(){const xs=state.items.filter(x=>state.selected.has(Number(x.id))),url=new URL(window.location.href);url.search='';url.hash='';url.searchParams.set('compare',xs.map(shareKey).join(','));return url.toString()}
