async function nativeShareComparison(){const url=comparisonShareUrl();if(navigator.share)try{await navigator.share({title:'Confronto alloggi FUORISEDE',text:'Guarda questo confronto di alloggi su FUORISEDE',url})}catch(e){}else await navigator.clipboard.writeText(url)}
function shareComparison(){const url=comparisonShareUrl(),message=`Guarda questo confronto di alloggi su FUORISEDE: ${url}`,overlay=document.createElement('div');overlay.className='shareoverlay';overlay.onclick=e=>{if(e.target===overlay)closeSharePanel()};overlay.innerHTML=`<div class="sharepanel" role="dialog" aria-modal="true"><h2>Condividi il confronto</h2><p class="note">Invialo a familiari o amici per valutarlo insieme.</p><div class="shareoptions"><a class="whatsapp" href="https://wa.me/?text=${encodeURIComponent(message)}" target="_blank" rel="noopener">WhatsApp</a><a href="mailto:?subject=${encodeURIComponent('Confronto alloggi FUORISEDE')}&body=${encodeURIComponent(message)}">Email</a><button onclick="copyComparisonLink(this)">Copia link</button><button class="native" onclick="nativeShareComparison()">Altre app</button></div><button class="shareclose" onclick="closeSharePanel()">Chiudi</button></div>`;document.body.appendChild(overlay)}
