if(sharedComparisonKeys.length>=2){let attempts=0;const sharedTimer=setInterval(()=>{attempts++;const found=state.items.filter(x=>sharedComparisonKeys.includes(shareKey(x)));if(found.length>=2&&(found.length===sharedComparisonKeys.length||attempts>=50)){clearInterval(sharedTimer);const type=accommodationType(found[0]),valid=found.filter(x=>accommodationType(x)===type).slice(0,3);state.selected=new Set(valid.map(x=>Number(x.id)));state.compareOpen=state.selected.size>=2;state.compareSeen=state.compareOpen;if(state.compareOpen)render()}else if(attempts>=50)clearInterval(sharedTimer)},200)}

