// Scheda operativa ricomposta sulla struttura della V3 Design originale.
function detailGalleryCell(x,index,extra=''){const src=x.photos?.[index];if(!src)return `<div class="ddphoto ddempty ${extra}"><span>Foto non disponibile</span></div>`;return `<button class="ddphoto ${extra}" style="background-image:url('${String(src).replaceAll("'","%27")}')" onclick="openPhotoViewer(${Number(x.id)},${index})" aria-label="Apri foto ${index+1}"></button>`}
function detailFeatureList(x){return features(x).map(f=>`<span class="ddfeature">${f}</span>`).join('')||'<span class="ddfeature">Dotazioni da verificare</span>'}
function designOperationalDetail(x){const id=Number(x.id),checked=state.selected.has(id),official=trackedSourceUrl(x,'detail'),nearby=demoSurroundings[x.campusReference?.campusId]||[],signals=statisticalSignals(x),photoCount=x.photos?.length||0;return `${nav()}<section class="dddetail"><button class="designback ddback" onclick="closeDetail()">← Tutti gli alloggi</button><div class="ddgallery">${detailGalleryCell(x,0,'ddmain')}${detailGalleryCell(x,1,'ddside')}${detailGalleryCell(x,2,'ddside')}${photoCount>3?`<button class="ddallphotos" onclick="openPhotoViewer(${id},0)">Vedi tutte le ${photoCount} foto</button>`:''}</div><div class="ddlayout"><article class="ddcontent"><div class="eyebrow">${x.publication?.status==='sandbox'?'DATI SANDBOX · NON PUBBLICITÀ':'SCHEDA AUTORIZZATA'} · ${x.city} · ${campusShort(x)}</div><h1>${x.title}</h1><p class="ddaddress">${x.address} · ${x.city}</p><div class="ddessentials"><div><small>DAL POLO</small><b>${bikeTimeText(x)}</b><span>${Number.isFinite(x.campusReference?.minutesBike)?'stima orientativa':'da verificare'}</span></div><div><small>DISPONIBILE</small><b>${availabilityText(x)}</b><span>${statusText(x)}</span></div><div><small>COSTO REALE</small><b>${costText(x)}</b><span>${x.realMonthlyCostStatus==='complete'?'canone + spese':'da completare'}</span></div></div><section class="ddsection"><h2>L’alloggio</h2><p>${x.details?.description||'Descrizione da integrare.'}</p><div class="ddfeatures">${detailFeatureList(x)}</div></section><section class="ddsection"><h2>Costi e disponibilità</h2><div class="ddrows"><div><span>Canone / mese</span><b>${euro(x.price)}</b></div><div><span>Costo reale stimato</span><b>${costText(x)}</b></div><div><span>Spese / utenze</span><b>${utilitiesText(x)}</b></div><div><span>Disponibilità</span><b>${availabilityText(x)}</b></div><div><span>Contratto</span><b>${contractText(x)}</b></div><div><span>Deposito</span><b>${x.details?.deposit||'Da verificare'}</b></div><div><span>Piano / ascensore</span><b>${x.details?.floor||'Da verificare'}</b></div></div></section><section class="ddsection"><h2>Da qui all’università</h2><div class="ddroute"><div><b>${bikeTimeText(x)}</b><span>BICI</span></div><div><b>${distanceText(x)}</b><span>DISTANZA</span></div></div>${routeUrl(x)?`<a class="ddmaplink" href="${routeUrl(x)}" target="_blank" rel="noopener noreferrer">Apri il percorso sulla mappa →</a>`:''}</section>${nearby.length?`<section class="ddsection"><h2>Il circondario</h2><div class="ddnearby">${nearby.map(([name,time])=>`<div><span>${name}</span><b>${time}</b></div>`).join('')}</div></section>`:''}<section class="ddsection"><h2>Informazioni, non promesse</h2><div class="ddtrust"><b>Completezza ${comparisonCompleteness(x)}/4</b><p>FUORISEDE distingue i dati letti nell’annuncio dalle informazioni ancora da verificare.</p><div class="ddtrustgrid"><span>Disponibilità<br><b>${statusText(x)}</b></span><span>Spese<br><b>${x.validation?.expensesDeclared?'Dato presente':'Da verificare'}</b></span><span>Contratto<br><b>${x.validation?.contractDeclared?'Dato presente':'Da verificare'}</b></span></div></div>${signals.length?`<div class="ddsignals">${signals.map(s=>`<span class="statmark${signalClass(s)}">${s}</span>`).join('')}</div>`:''}</section>${detailMapBlock(x)}</article><aside class="ddaside"><div class="ddprice">${euro(x.price)} <small>/ mese</small></div><div class="ddreal"><span>Costo reale stimato</span><b>${costText(x)}</b></div><div class="ddavailable">${availabilityText(x)}</div>${official?`<a class="ddoriginal" href="${official}" target="_blank" rel="noopener noreferrer">Apri l’annuncio originale ↗</a>`:`<button class="ddsecondary" onclick="unavailableAction('Il collegamento originale non è disponibile per questa scheda.')">Annuncio originale non disponibile</button>`}<button class="ddsecondary ${state.favs.has(id)?'active':''}" onclick="toggleFav(${id})">${state.favs.has(id)?'♥ Salvato':'♡ Salva'}</button><button class="ddsecondary ${checked?'active':''}" onclick="toggleCompare('${id}',${!checked})">${checked?'✓ Nel confronto':'Confronta'}</button>${needsIntegration(x)?`<button class="ddsecondary" onclick="requestIntegration(${id})">Richiedi integrazione</button>`:''}<p>Prima di pagare caparre o anticipi verifica interlocutore, contratto e disponibilità reale.</p></aside></div></section>${compareDock()}`}
