// Navigazione finale e dati reali dei servizi vicini.
const comparisonWithBottomNavigation=comparison;
function returnToChoices(){state.view='list';state.compareOpen=false;state.detail=null;render();window.scrollTo({top:0,behavior:'smooth'})}
comparison=function(){const html=comparisonWithBottomNavigation(),anchor='<div class="designcomparefoot">',pos=html.indexOf(anchor);if(pos<0)return html;const navigation=`<div class="comparetopnav" aria-label="Azioni sugli alloggi confrontati"><button onclick="setView('map')">Mappa</button><button class="primary" onclick="returnToChoices()">Le mie scelte</button></div>`;return `${html.slice(0,pos)}${navigation}${html.slice(pos)}`};

state.nearbyCache=state.nearbyCache||{};
function renderNearbyItems(items){return items.map(item=>`<div><span>${item.name||item.label}</span><b>${item.metres<1000?`${item.metres} m`:`${(item.metres/1000).toLocaleString('it-IT',{maximumFractionDigits:1})} km`} · ≈ ${item.minutes} min a piedi</b></div>`).join('')}
function applyNearbyItems(x,items){if(state.detail!==Number(x.id)||!items?.length)return;let grid=document.querySelector('.ddnearby');if(grid){grid.innerHTML=renderNearbyItems(items);return}const sections=[...document.querySelectorAll('.ddsection')],information=sections.find(section=>section.querySelector('h2')?.textContent.includes('Informazioni'));if(!information)return;const section=document.createElement('section');section.className='ddsection';section.innerHTML=`<h2>Nei dintorni</h2><div class="ddnearby">${renderNearbyItems(items)}</div><p class="ddnearbySource">Distanze indicative ricavate dalle coordinate dell’alloggio e dai dati OpenStreetMap.</p>`;information.before(section)}
async function loadNearbyForListing(x){if(!Number.isFinite(x.lat)||!Number.isFinite(x.lng))return;const key=Number(x.id);if(state.nearbyCache[key]){applyNearbyItems(x,state.nearbyCache[key]);return}try{const response=await fetch(`/api/nearby?lat=${x.lat}&lng=${x.lng}`);if(!response.ok)return;const data=await response.json();state.nearbyCache[key]=data.items||[];applyNearbyItems(x,state.nearbyCache[key])}catch(error){console.info('Servizi nei dintorni non disponibili',error)}}
const openDetailWithNearby=openDetail;
openDetail=function(id){openDetailWithNearby(id);const x=state.items.find(item=>Number(item.id)===Number(id));if(x)setTimeout(()=>loadNearbyForListing(x),0)};

const detailWithBackToTop=detailView;
detailView=function(x){const html=detailWithBackToTop(x),pos=html.lastIndexOf('</section>');if(pos<0)return html;setTimeout(()=>loadNearbyForListing(x),0);return `${html.slice(0,pos)}<div class="ddbacktotop"><button onclick="window.scrollTo({top:0,behavior:'smooth'})">↑ Torna su</button></div>${html.slice(pos)}`};

document.head.insertAdjacentHTML('beforeend',`<style>.comparetopnav{display:flex;justify-content:flex-end;gap:8px;margin:28px 0 4px}.comparetopnav button{border:1px solid var(--design-line);border-radius:999px;padding:11px 15px;background:#fff;color:#171715;font-size:10px;font-weight:750}.comparetopnav .primary{border-color:#171715;background:#171715;color:#fff}.card .badge,.card .statmark,.card .statmark.warn,.card .integrationprompt{background:transparent!important;color:#171715!important}.card .badge{border:1px solid #8fc5ae!important}.card .badge.warn,.card .statmark.warn{border-color:#d7a451!important}.card .statmark{border:1px solid #8fc5ae}.ddfeature,.ddsignals .statmark,.ddsignals .statmark.warn,.integrationprompt{color:#171715!important}.ddbacktotop{display:flex;justify-content:flex-end;margin:28px 0 4px}.ddbacktotop button{border:1px solid var(--design-line);border-radius:999px;padding:10px 14px;background:#fff;color:#171715;font-size:10px;font-weight:750}.ddnearbySource{margin:9px 0 0!important;color:var(--design-muted)!important;font-size:8px!important}</style>`);

