render=function(){renderWithGlobalBackToTop();const root=document.getElementById('v3-root');if(!root||root.querySelector('.ddbacktotop,.globalbacktotop'))return;const control=document.createElement('div');control.className='globalbacktotop';control.innerHTML='<button onclick="window.scrollTo({top:0,behavior:\'smooth\'})">↑ Torna su</button>';root.appendChild(control)};
