// Ultime correzioni di collaudo: il logo torna alla home, il confronto usa
// sempre la sede selezionata e i filtri della mappa restano presenti ma compatti.
function goHome(){state.detail=null;state.compareOpen=false;state.view='list';render();window.scrollTo({top:0,behavior:'smooth'})}
const approvedLogo=document.querySelector('.approved-logo');
if(approvedLogo){approvedLogo.setAttribute('role','link');approvedLogo.setAttribute('tabindex','0');approvedLogo.setAttribute('aria-label','Vai alla home di FUORISEDE');approvedLogo.addEventListener('click',goHome);approvedLogo.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();goHome()}})}

function refreshCurrentStudyDistances(){const site=selectedStudySite(),campusId=state.campus||state.zone;if(!site||!campusId)return;state.items.filter(x=>(!state.city||x.city===state.city)&&Number.isFinite(x.lat)&&Number.isFinite(x.lng)).forEach(x=>{const km=haversineKm(x.lat,x.lng,site.lat,site.lng)*1.18;x.campusReference={campusId,campusName:site.name,distanceKm:Number(km.toFixed(1)),minutesBike:Math.max(2,Math.round(km/15*60)),travelEstimate:true}})}
const openComparisonWithFreshDistances=openComparison;
openComparison=function(){refreshCurrentStudyDistances();openComparisonWithFreshDistances()};

const renderWithMapFilterMode=render;
render=function(){renderWithMapFilterMode();document.body.classList.toggle('map-mode',state.view==='map'&&!state.detail&&!state.compareOpen)};
