// Recupero delle azioni utili della precedente scheda, senza creare contatti fittizi.
function directContactAction(x){if(sourceType(x)!=='direct')return'';const href=x.publication?.contactUrl||x.publication?.contactEmail&&`mailto:${x.publication.contactEmail}`||x.publication?.contactPhone&&`tel:${x.publication.contactPhone}`;return href?`<a class="ddsecondary" href="${href}">Contatta l’offerente</a>`:''}
