detailView=function(x){const id=Number(x.id),interest=Number(x.candidates||0)+(state.applied.has(id)?1:0),heart=`<button class="ddphotoheart ${state.favs.has(id)?'active':''}" onclick="toggleFav(${id})" aria-label="${state.favs.has(id)?'Rimuovi dai preferiti':'Aggiungi ai preferiti'}">${state.favs.has(id)?'♥':'♡'}</button>`,interestBlock=`<div class="ddinterest">${interest?`<b>${interest}</b> ${interest===1?'studente interessato':'studenti interessati'}`:'Nessuno ha ancora segnalato interesse'}</div><button class="ddoriginal" onclick="quickApply(${id})" ${state.applied.has(id)?'disabled':''}>${state.applied.has(id)?'Interesse registrato ✓':'Mi interessa'}</button>`,integration=`<button class="ddsecondary" onclick="requestIntegration(${id})">Richiedi integrazione</button>`;let html=detailWithRecoveredActions(x);html=html.replace('</div><div class="ddlayout">',`${heart}</div><div class="ddlayout">`).replace('<section class="ddsection"><h2>Costi e disponibilità</h2>','<section class="ddsection ddcostbox"><h2>Costi e disponibilità</h2>');html=html.replace(/<button class="ddsecondary [^"]*" onclick="toggleFav\([^<]+<\/button>/,'').replace(/<button class="ddsecondary" onclick="requestIntegration\([^<]+<\/button>/g,'');const asideStart=html.indexOf('<aside class="ddaside">'),availableEnd=html.indexOf('</div>',html.indexOf('<div class="ddavailable">',asideStart));if(asideStart>=0&&availableEnd>=0)html=`${html.slice(0,availableEnd+6)}${interestBlock}${html.slice(availableEnd+6)}`;const safety=html.indexOf('<p>Prima di pagare',asideStart);if(safety>=0)html=`${html.slice(0,safety)}${directContactAction(x)}${integration}${html.slice(safety)}`;return html};
