// Aggiornamento locale del confronto dalla mappa: nessun nuovo render, quindi
// zoom e tessere restano intatti e il marker torna subito pieno quando rimosso.
function mapPopupContent(x){const key=Number(x.id),selected=state.selected.has(key),favorite=state.favs.has(key);return `<b>${favorite?'♥ Preferito · ':''}${selected?'★ Nel confronto · ':''}${x.title}</b><br>${euro(x.price)} / mese<br><small>${x.locationStatus==='approximate_area'?'Posizione indicativa':'Posizione verificata sulla via'}</small><div class="pinactions"><button class="pinopen" onclick="openDetail(${key})">Apri la scheda</button><button class="pincompare" onclick="mapCompareAction(${key})">${selected?'✓ Togli dal confronto':'⇄ Confronta'}</button></div>`}
function refreshMapComparison(activeId){const context=activeMapMarkers.get('demo-map');if(!context)return;context.markers.forEach(({marker,x})=>{const key=Number(x.id),selected=state.selected.has(key),favorite=state.favs.has(key);marker.setStyle(markerAppearance(x,false));marker.setTooltipContent(`${favorite?'♥ ':''}${selected?'★ ':''}${euro(x.price)}`);marker.getPopup()?.setContent(mapPopupContent(x));if(selected)marker.bringToBack()});const active=context.markers.get(Number(activeId));if(active){active.marker.setStyle(markerAppearance(active.x,false));active.marker.openPopup()}document.querySelector('.comparedock')?.remove();if(state.selected.size>=2)document.getElementById('v3-root')?.insertAdjacentHTML('beforeend',compareDock())}
mapCompareAction=function(id){const key=Number(id),candidate=state.items.find(x=>Number(x.id)===key);if(!candidate)return;const removing=state.selected.has(key);if(!mapComparisonSessionStarted&&!removing){state.selected.clear();state.compareOpen=false;state.compareSeen=false}mapComparisonSessionStarted=true;if(removing){state.selected.delete(key)}else{if(state.selected.size){const first=state.items.find(x=>state.selected.has(Number(x.id))),required=accommodationType(first);if(!required||accommodationType(candidate)!==required){alert(`Puoi confrontare solo ${accommodationLabel(required)} con ${accommodationLabel(required)}.`);return}}if(state.selected.size>=3){alert('Puoi confrontare fino a 3 alloggi.');return}state.selected.add(key)}if(state.selected.size<2)state.compareOpen=false;state.mapActiveListingId=key;refreshMapComparison(key)};

// Nella scheda, i due ritorni operativi restano affiancati sulla destra.
const detailWithMapReturn=detailView;
detailView=function(x){let html=detailWithMapReturn(x);if(state.selected.size>=2&&html.includes('ddreturncompare')&&!html.includes('ddreturnmap'))html=html.replace(/(<button class="ddreturncompare"[\s\S]*?<\/button>)/,`<div class="dddetailnavactions"><button class="ddreturnmap" onclick="setView('map')">← Torna alla mappa</button>$1</div>`);return html};
document.head.insertAdjacentHTML('beforeend',`<style>.dddetailnavactions{display:flex;align-items:center;gap:18px;margin-left:auto}.ddreturnmap{border:0;background:transparent;color:#171715;padding:0;font-size:11px;font-weight:400;cursor:pointer}.ddreturnmap:hover{text-decoration:underline}@media(max-width:700px){.dddetailnavactions{gap:10px;align-items:flex-start}.ddreturnmap,.ddreturncompare{max-width:120px;text-align:right}}</style>`);

// Il ritorno dalla scheda o dal confronto prosegue la selezione corrente e non
// avvia una nuova sessione della mappa.
function returnToMapKeepingComparison(){state.detail=null;state.compareOpen=false;state.view='map';mapComparisonSessionStarted=true;render();window.scrollTo({top:0,behavior:'smooth'})}
const detailWithPreservedMapSelection=detailView;
detailView=function(x){return detailWithPreservedMapSelection(x).replace('class="ddreturnmap" onclick="setView(\'map\')"','class="ddreturnmap" onclick="returnToMapKeepingComparison()"')};
const comparisonWithPreservedMapSelection=comparison;
comparison=function(){return comparisonWithPreservedMapSelection().replaceAll('onclick="setView(\'map\')"','onclick="returnToMapKeepingComparison()"')};

// Aprire il popup di un marker gia' selezionato non ne modifica l'aspetto:
// resta il cerchio vuoto che identifica il confronto.
const selectMapListingWithStableSelection=selectMapListing;
selectMapListing=function(mapId,id,pan=true){selectMapListingWithStableSelection(mapId,id,pan);const context=activeMapMarkers.get(mapId),entry=context?.markers.get(Number(id));if(entry&&state.selected.has(Number(id))){entry.marker.setStyle(markerAppearance(entry.x,false));entry.marker.bringToBack()}};

// La mappa estende sempre il confronto esistente: nessuna selezione precedente
// viene cancellata automaticamente quando si aggiunge un nuovo pin.
mapCompareAction=function(id){const key=Number(id),candidate=state.items.find(x=>Number(x.id)===key);if(!candidate)return;const removing=state.selected.has(key);mapComparisonSessionStarted=true;if(removing){state.selected.delete(key)}else{if(state.selected.size){const first=state.items.find(x=>state.selected.has(Number(x.id))),required=accommodationType(first);if(!required||accommodationType(candidate)!==required){alert(`Puoi confrontare solo ${accommodationLabel(required)} con ${accommodationLabel(required)}.`);return}}if(state.selected.size>=3){alert('Puoi confrontare fino a 3 alloggi.');return}state.selected.add(key)}if(state.selected.size<2)state.compareOpen=false;state.mapActiveListingId=key;refreshMapComparison(key)};

// Protezione della selezione gia' esistente quando si entra nella mappa.
state.mapBaselineSelection=new Set();
state.mapExplicitlyRemoved=new Set();
function rememberMapSelection(){state.mapBaselineSelection=new Set(state.selected);state.mapExplicitlyRemoved=new Set()}
const setViewWithSelectionBaseline=setView;
setView=function(view){if(view==='map')rememberMapSelection();setViewWithSelectionBaseline(view)};
returnToMapKeepingComparison=function(){rememberMapSelection();state.detail=null;state.compareOpen=false;state.view='map';mapComparisonSessionStarted=true;render();window.scrollTo({top:0,behavior:'smooth'})};
const resetComparisonStateWithMapBaseline=resetComparisonState;
resetComparisonState=function(){resetComparisonStateWithMapBaseline();state.mapBaselineSelection.clear();state.mapExplicitlyRemoved.clear()};
const clearComparisonWithMapBaseline=clearComparison;
clearComparison=function(){state.mapBaselineSelection.clear();state.mapExplicitlyRemoved.clear();clearComparisonWithMapBaseline()};

mapCompareAction=function(id){const key=Number(id),candidate=state.items.find(x=>Number(x.id)===key);if(!candidate)return;state.mapBaselineSelection.forEach(saved=>{if(!state.mapExplicitlyRemoved.has(saved))state.selected.add(saved)});const removing=state.selected.has(key);mapComparisonSessionStarted=true;if(removing){state.selected.delete(key);state.mapExplicitlyRemoved.add(key)}else{if(state.selected.size){const first=state.items.find(x=>state.selected.has(Number(x.id))),required=accommodationType(first);if(!required||accommodationType(candidate)!==required){alert(`Puoi confrontare solo ${accommodationLabel(required)} con ${accommodationLabel(required)}.`);return}}if(state.selected.size>=3){alert('Puoi confrontare fino a 3 alloggi.');return}state.mapExplicitlyRemoved.delete(key);state.selected.add(key)}if(state.selected.size<2)state.compareOpen=false;state.mapActiveListingId=key;refreshMapComparison(key)};
toggleCompareFromMap=function(id){mapCompareAction(id)};

// Tipografia uniforme per i tre comandi di navigazione della scheda.
document.head.insertAdjacentHTML('beforeend',`<style>.dddetailnav .designback,.dddetailnav .ddreturnmap,.dddetailnav .ddreturncompare{font-family:inherit!important;font-size:11px!important;font-weight:400!important;font-style:normal!important;line-height:1.25!important;letter-spacing:0!important;text-transform:none!important;color:var(--design-muted)!important}</style>`);


/* Correzione layout desktop: la pagina Mappa occupa tutta la griglia. */
document.head.insertAdjacentHTML('beforeend',`<style>.mapview{grid-column:1/-1;width:100%;min-width:0}.mapworkspace{width:100%;min-width:0}.mapcanvas{min-width:0}@media(min-width:701px){.mapcanvas,#demo-map,#home-map{width:100%}}</style>`);


/* Correzione completa desktop: confronto, popup e collegamento alla mappa. */
function showListingOnMap(id){
  state.detail=null;
  state.compareOpen=false;
  state.view='map';
  state.mapActiveListingId=Number(id);
  rememberMapSelection();
  render();
  window.scrollTo({top:0,behavior:'smooth'});
}
document.head.insertAdjacentHTML('beforeend',`<style>
.compareview,.compareview.designcompare{grid-column:1/-1!important;width:100%!important;min-width:0!important;margin-left:auto!important;margin-right:auto!important}
.compareview .designtable,.compareview .comparecards{width:100%;min-width:0}
.cardactions{gap:10px;flex-wrap:wrap}
.cardmaplink{border:0;background:transparent;color:#171715;padding:6px 4px;font-size:10px;font-weight:650;text-decoration:underline;cursor:pointer}
.leaflet-popup-content-wrapper{max-width:min(280px,calc(100vw - 48px))}
.leaflet-popup-content{max-width:240px!important;margin:12px 14px!important;overflow-wrap:anywhere}
.leaflet-popup-content .pinactions{flex-wrap:wrap}
.leaflet-popup-content .pinactions button{min-width:0;white-space:normal}
@media(max-width:700px){
  .cardactions{align-items:center}
  .cardmaplink{order:2;width:100%;text-align:left;padding-top:2px}
}
</style>`);
const initMapWithContainedPopup=initMap;
initMap=function(id='demo-map',items=state.items,attempt=0){
  initMapWithContainedPopup(id,items,attempt);
  const contain=(tries=0)=>{
    const context=activeMapMarkers.get(id);
    if(!context&&tries<30){setTimeout(()=>contain(tries+1),100);return}
    context?.markers.forEach(({marker})=>{
      const popup=marker.getPopup();
      if(!popup)return;
      popup.options.autoPan=true;
      popup.options.keepInView=true;
      popup.options.autoPanPaddingTopLeft=L.point(24,70);
      popup.options.autoPanPaddingBottomRight=L.point(24,24);
    });
  };
  setTimeout(()=>contain(),120);
};


/* Distribuzione anti-sovrapposizione delle etichette prezzo sulla mappa. */
function arrangeMapPriceLabels(mapId='demo-map'){
  const context=activeMapMarkers.get(mapId);
  if(!context||!window.L)return;
  const size=context.map.getSize(),placed=[];
  const entries=[...context.markers.entries()].sort(([a],[b])=>{
    const sa=state.selected.has(Number(a))?0:1,sb=state.selected.has(Number(b))?0:1;
    return sa-sb;
  });
  const candidates=[
    {direction:'top',rect:(p,w,h)=>({x:p.x-w/2,y:p.y-h-15,w,h})},
    {direction:'right',rect:(p,w,h)=>({x:p.x+15,y:p.y-h/2,w,h})},
    {direction:'bottom',rect:(p,w,h)=>({x:p.x-w/2,y:p.y+15,w,h})},
    {direction:'left',rect:(p,w,h)=>({x:p.x-w-15,y:p.y-h/2,w,h})}
  ];
  const overlap=(a,b)=>Math.max(0,Math.min(a.x+a.w,b.x+b.w)-Math.max(a.x,b.x))*Math.max(0,Math.min(a.y+a.h,b.y+b.h)-Math.max(a.y,b.y));
  entries.forEach(([key,{marker,x}],index)=>{
    const tooltip=marker.getTooltip();
    if(!tooltip)return;
    const p=context.map.latLngToContainerPoint(marker.getLatLng());
    const label=`${state.favs.has(Number(key))?'♥ ':''}${state.selected.has(Number(key))?'★ ':''}${euro(x.price)}`;
    const w=Math.max(48,Math.min(110,label.length*7+18)),h=28;
    let best=null;
    candidates.forEach((candidate,candidateIndex)=>{
      const rect=candidate.rect(p,w,h);
      const outside=Math.max(0,-rect.x)+Math.max(0,-rect.y)+Math.max(0,rect.x+rect.w-size.x)+Math.max(0,rect.y+rect.h-size.y);
      const collisions=placed.reduce((sum,other)=>sum+overlap(rect,other),0);
      const selectedBias=state.selected.has(Number(key))?((index+candidateIndex)%candidates.length)*2:candidateIndex;
      const score=outside*100+collisions*10+selectedBias;
      if(!best||score<best.score)best={...candidate,rect,score};
    });
    tooltip.options.direction=best.direction;
    tooltip.options.offset=L.point(0,0);
    placed.push(best.rect);
    if(marker.isTooltipOpen()){marker.closeTooltip();marker.openTooltip()}
  });
}
function installMapLabelCollisionHandling(mapId='demo-map',tries=0){
  const context=activeMapMarkers.get(mapId);
  if(!context&&tries<30){setTimeout(()=>installMapLabelCollisionHandling(mapId,tries+1),100);return}
  if(!context||context.map.__fuorisedeLabelCollision)return;
  context.map.__fuorisedeLabelCollision=true;
  const update=()=>requestAnimationFrame(()=>arrangeMapPriceLabels(mapId));
  context.map.on('zoomend moveend resize',update);
  update();
}
const initMapWithSeparatedPriceLabels=initMap;
initMap=function(id='demo-map',items=state.items,attempt=0){
  initMapWithSeparatedPriceLabels(id,items,attempt);
  setTimeout(()=>installMapLabelCollisionHandling(id),180);
};
const refreshMapComparisonWithSeparatedLabels=refreshMapComparison;
refreshMapComparison=function(activeId){
  refreshMapComparisonWithSeparatedLabels(activeId);
  setTimeout(()=>arrangeMapPriceLabels('demo-map'),40);
};
